import json, re
data = json.load(open('batch_0034.json', encoding='utf-8'))

def hira_ratio(s):
    if not s: return 0
    hira = len(re.findall(r'[぀-ゟ]', s))
    return hira / max(len(s),1)

def fix(s):
    if not s:
        return s
    try:
        b = s.encode('latin1', errors='strict')
    except Exception:
        return s
    return b.decode('utf-8', errors='ignore')

results = []
for row in data:
    idx = row['idx']
    name = row['name']
    body = row.get('body','')
    orig_h = hira_ratio(body)
    fixed_body = fix(body)
    fixed_h = hira_ratio(fixed_body)
    best_h = max(orig_h, fixed_h)
    results.append((idx, name, orig_h, fixed_h, best_h))

bad = [r for r in results if r[4] < 0.02]
print("LOW HIRAGANA RATIO (likely unrecoverable or needs check):")
for r in bad:
    print(r)
EOF

